import * as stylex from "@stylexjs/stylex";
import * as React from "react";

function Foo() {
  const styles = stylex.create({
    div: { color: "red" },
  });
  return <div {...stylex.props(styles.div)}>Hello, foo!</div>;
}

function Bar() {
  const styles = stylex.create({
    div: { color: "blue" },
  });
  return <div {...stylex.props(styles.div)}>Hello, bar!</div>;
}

export function App() {
  return (
    <>
      <Foo />
      <Bar />
    </>
  );
}

